Here is the root cause:
The call to __skb_flow_dissect in bond_flow_dissect passed NULL as the net pointer, which is no longer allowed after commit 3cbf4ffba5ee. When a bare skb (without a dev or sk) was processed, the function triggered a WARNING.

Here is the patch:
 /* Extract the appropriate headers based on bond's xmit policy */
 static bool bond_flow_dissect(struct bonding *bond, struct sk_buff *skb, const void *data,
 			      __be16 l2_proto, int nhoff, int hlen, struct flow_keys *fk)
 {
 	bool l34 = bond->params.xmit_policy == BOND_XMIT_POLICY_LAYER34;
 	int ip_proto = -1;

 	switch (bond->params.xmit_policy) {
 	case BOND_XMIT_POLICY_ENCAP23:
 	case BOND_XMIT_POLICY_ENCAP34:
 		memset(fk, 0, sizeof(*fk));
-		return __skb_flow_dissect(NULL, skb, &flow_keys_bonding,
-					  fk, data, l2_proto, nhoff, hlen, 0);
+		return __skb_flow_dissect(dev_net(bond->dev), skb,
+					  &flow_keys_bonding, fk, data,
+					  l2_proto, nhoff, hlen, 0);
 	default:
 		break;
 	}

 	fk->ports.ports = 0;
 	memset(&fk->icmp, 0, sizeof(fk->icmp));
 	if (!bond_flow_ip(skb, fk, data, hlen, l2_proto, &nhoff, &ip_proto, l34))
 		return false;

 	/* ICMP error packets contains at least 8 bytes of the header
 	 * of the packet which generated the error. Use this information
 	 * to correlate ICMP error packets within the same flow which
 	 * generated the error.
 	 */
 	if (ip_proto == IPPROTO_ICMP || ip_proto == IPPROTO_ICMPV6) {
 		skb_flow_get_icmp_tci(skb, &fk->icmp, data, nhoff, hlen);
 		if (ip_proto == IPPROTO_ICMP) {
 			if (!icmp_is_err(fk->icmp.type))
 				return true;

 			nhoff += sizeof(struct icmphdr);
 		} else if (ip_proto == IPPROTO_ICMPV6) {
 			if (!icmpv6_is_err(fk->icmp.type))
 				return true;

 			nhoff += sizeof(struct icmp6hdr);
 		}
 		return bond_flow_ip(skb, fk, data, hlen, l2_proto, &nhoff, &ip_proto, l34);
 	}

 	return true;
 }



